      "path": "/projects/capacitor-codescanner/docs/api",
      "html": "<div class=\"api-reference\"><ul>\n<li><a href=\"/de/projects/capacitor-codescanner/docs/api#present\"><code>present(...)</code></a></li>\n<li><a href=\"/de/projects/capacitor-codescanner/docs/api#addlistenercodescannercatchevent-\"><code>addListener('CodeScannerCatchEvent', ...)</code></a></li>\n<li><a href=\"/de/projects/capacitor-codescanner/docs/api#interfaces\">Schnittstellen</a></li>\n<li><a href=\"/de/projects/capacitor-codescanner/docs/api#type-aliases\">Typaliase</a></li>\n</ul>\n<p></p>\n<span id=\"present(...)\"></span><section class=\"api-entry\"><h4 id=\"present\"><code>method</code> present(...)</h4><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code style=\"color:#e1e4e8\"><span class=\"line\"><span style=\"color:#B392F0\">present</span>(scannerOption: ScannerOption) <span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> Promise</span><span style=\"color:#F97583\">&lt;void&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><table>\n<thead>\n<tr>\n<th>Parameter</th>\n<th>Typ</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong><code>scannerOption</code></strong></td>\n<td><code><a href=\"#scanneroption\">ScannerOption</a></code></td>\n</tr>\n</tbody>\n</table><hr><span id=\"addlistener('codescannercatchevent'%2C-...)\"></span></section>\n\n\n<section class=\"api-entry\"><h4 id=\"addlistenercodescannercatchevent-\"><code>method</code> addListener('CodeScannerCatchEvent', ...)</h4><div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code style=\"color:#e1e4e8\"><span class=\"line\"><span style=\"color:#B392F0\">addListener</span>(eventName: <span style=\"color:#9ECBFF\">'CodeScannerCatchEvent'</span>, listenerFunc: (<span style=\"color:#FFAB70\">event</span><span style=\"color:#F97583\">:</span> { <span style=\"color:#FFAB70\">code</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span>; }) <span style=\"color:#F97583\">=&gt;</span><span style=\"color:#F97583\"> void</span>) <span style=\"color:#F97583\">=&gt;</span><span style=\"color:#79B8FF\"> Promise</span><span style=\"color:#F97583\">&lt;</span>PluginListenerHandle<span style=\"color:#F97583\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><table>\n<thead>\n<tr>\n<th>Parameter</th>\n<th>Typ</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong><code>eventName</code></strong></td>\n<td><code>'CodeScannerCatchEvent'</code></td>\n</tr>\n<tr>\n<td><strong><code>listenerFunc</code></strong></td>\n<td><code>(event: { code: string; }) =&gt; void</code></td>\n</tr>\n</tbody>\n</table><p><strong>Rückgabe:</strong> <code>Promise&lt;<a href=\"#pluginlistenerhandle\">PluginListenerHandle</a>&gt;</code></p><hr></section>\n\n\n\n<h3 id=\"schnittstellen\"><span id=\"interfaces\" data-docs-heading-alias=\"\" aria-hidden=\"true\"></span><a class=\"header-anchor-link\" href=\"#schnittstellen\" aria-hidden=\"true\"></a> Schnittstellen</h3>\n<section class=\"api-entry\"><h4 id=\"scanneroption\"><code>interface</code> <a class=\"header-anchor-link\" href=\"#scanneroption\" aria-hidden=\"true\"></a> ScannerOption</h4><table>\n<thead>\n<tr>\n<th>Eigenschaft</th>\n<th>Typ</th>\n<th>Beschreibung</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong><code>detectionWidth</code></strong></td>\n<td><code>number</code></td>\n<td>Breite des Erkennungsbereichs im Verhältnis zur verfügbaren Breite (0–1). Der Standardwert ist 0,4.</td>\n</tr>\n<tr>\n<td><strong><code>detectionHeight</code></strong></td>\n<td><code>number</code></td>\n<td>Höhe des Erkennungsbereichs im Verhältnis zur Erkennungsbreite. Der Standardwert unter iOS ist 1; unter Android sind 0,15–0,2 üblich.</td>\n</tr>\n<tr>\n<td><strong><code>enableCloseButton</code></strong></td>\n<td><code>boolean</code></td>\n<td>Schließen-Schaltfläche oben links im Scanbereich aktivieren (Standard: true)</td>\n</tr>\n<tr>\n<td><strong><code>sheetScreenRatio</code></strong></td>\n<td><code>number</code></td>\n<td>Verhältnis des Scanbereichs (Größe des Sheet-Modals) zur Bildschirmgröße festlegen. Der Standardwert ist 0,9 unter Android und 1 (pageSheet) unter iOS.</td>\n</tr>\n<tr>\n<td><strong><code>CodeTypes</code></strong></td>\n<td><code>MetadataObjectTypes[]</code></td>\n<td>Zu erkennende Codetypen festlegen (Standard: [\"qr\", \"code39\", \"ean13\"])</td>\n</tr>\n<tr>\n<td><strong><code>isMulti</code></strong></td>\n<td><code>boolean</code></td>\n<td>Mehrfachscan-Modus aktivieren (Standard: false)</td>\n</tr>\n<tr>\n<td><strong><code>enableAutoLight</code></strong></td>\n<td><code>boolean</code></td>\n<td>Automatische Beleuchtung bei Dunkelheit aktivieren (Standard: true)</td>\n</tr>\n</tbody>\n</table></section>\n\n<section class=\"api-entry\"><h4 id=\"pluginlistenerhandle\"><code>interface</code> <a class=\"header-anchor-link\" href=\"#pluginlistenerhandle\" aria-hidden=\"true\"></a> PluginListenerHandle</h4><table>\n<thead>\n<tr>\n<th>Eigenschaft</th>\n<th>Typ</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td><strong><code>remove</code></strong></td>\n<td><code>() =&gt; Promise&lt;void&gt;</code></td>\n</tr>\n</tbody>\n</table></section>\n\n<h3 id=\"typaliase\"><span id=\"type-aliases\" data-docs-heading-alias=\"\" aria-hidden=\"true\"></span><a class=\"header-anchor-link\" href=\"#typaliase\" aria-hidden=\"true\"></a> Typaliase</h3>\n<section class=\"api-entry\"><h4 id=\"metadataobjecttypes\"><code>type alias</code> <a class=\"header-anchor-link\" href=\"#metadataobjecttypes\" aria-hidden=\"true\"></a> MetadataObjectTypes</h4><p class=\"api-signature\"><code>'aztec' | 'code128' | 'code39' | 'code39Mod43' | 'code93' | 'dataMatrix' | 'ean13' | 'ean8' | 'face' | 'interleaved2of5' | 'itf14' | 'pdf417' | 'qr' | 'upce' | 'catBody' | 'dogBody' | 'humanBody' | 'salientObject'</code></p></section>\n\n</div>",
